  'spol.title': 'Support policy',
  'spol.lead': 'One version says what the desk promises, when it is open, who is woken when a promise is missed, and what the AI may answer alone. Editing means publishing a new version — the old one stays readable, because six months from now the only defensible answer to “why was my P1 not escalated?” is the policy that was active then.',
