  // ---- PC-56 ADMIN-2d · a PLATFORM reply to the farmer (0101) ----
  'prep.title': 'Reply to the farmer',
  'prep.lead': 'A message from KRISHALAYA to the person who raised this ticket. It is not a message from their FPO’s desk and it does not pretend to be — the platform cannot post into a tenant’s conversation without inventing an account inside that tenant, so this goes out through the notification rail attributed to us.',
  'prep.visibleToTenant': 'THE TENANT’S OWN DESK CAN READ THIS. The platform talking to a tenant’s member behind that tenant’s back would be a breach of trust whatever the message said, so every reply here is readable by them — and not editable by them.',
  'prep.body': 'What to tell them',
  'prep.bodyHint': 'At least 20 characters. Your words are sent verbatim — nothing summarises or shortens them. A notification saying “noted” uses up the one message they will read.',
  'prep.language': 'Language',
  'prep.languageHint': 'The language YOU are writing in. There is no default: the farmer being able to read this is your call, not a guess.',
  'prep.lang.en': 'English',
  'prep.lang.hi': 'Hindi',
  'prep.lang.gu': 'Gujarati',
  'prep.send': 'Queue this reply',
  'prep.queuedWarn': 'PRESSING THIS DOES NOT SEND YET. The reply is recorded and delivered within a minute by the part of the platform that owns notifications. The status below is the truth — watch it change.',
  'prep.historyTitle': 'Replies on this ticket',
  'prep.none': 'The platform has not replied to this farmer.',
