  'prep.smsNote': 'Delivery today means in-app and push. The SMS template is written but inactive until the DLT registration ids are issued, so nothing here claims to have texted anybody.',
  'prep.ok.queued': 'Recorded. Nobody has been contacted yet — the status below will change within a minute.',
